import json
from books.penwick import *
class T:
    def __init__(s, rs): s.rs=list(rs); s.log=[]
    def send(s, m, p, h, b):
        s.log.append((m,p,h,b)); r=s.rs.pop(0)
        if r is None: raise ConnectionError()
        return r
    def sleep(s, x): s.log.append(('sleep',x))
def R(st, body=None, h=None): return Response(st, h or {}, json.dumps(body or {}).encode())
tr={'id':'tr_1','source':'a','destination':'b','amount':5,'currency':'EUR','reference':'r','status':'reversed'}
t=T([None, R(429,{},{'retry-after':'3'}), R(503), R(200,dict(tr,status='pending')), R(200,tr)])
print(reverse_transfer(t,'tr_1')); [print(x) for x in t.log]
tr2=dict(tr,status='pending')
t=T([R(409,{'error':{'code':'idempotency_in_progress'}},{'Retry-After':'0'}), R(201,tr2)])
create_transfer(t,'INV-1','a','b',5,'EUR'); [print(x) for x in t.log]
EOF
python /tmp/t.py && python -m unittest 2>&1 | tail -3
